#!/usr/bin/env python3
"""
Falsifier for eta_int_modulator: compliant records must not bypass the
near-copy/recidivism severe penalty tier.

This imports the real target module by absolute package path and exercises the
runtime behavior. It prints FALSIFIED and raises AssertionError iff the defect is
present: record.compliant=True causes an immediate 1.0 return even though the
record is a near-copy/recidivist case that should be penalized.
"""

import copy
import inspect
from types import SimpleNamespace

from bench.dm import _divergence as target


class ProbeRecord(SimpleNamespace):
    """Attribute + mapping-style probe record for the real eta_int_modulator."""

    def __init__(self):
        super().__init__(
            # The buggy early-return guard:
            compliant=True,

            # Severe-tier preconditions:
            any_near_copy=True,
            near_copy=True,
            is_near_copy=True,
            recidivist=True,
            recidivism=True,
            cross_round_recidivist=True,
            prior_similar_findings=["previous near-copy finding"],
            repeated_issue=True,

            # Harmless defaults commonly used by policy/scoring code:
            finding_id="falsifier-near-copy-recidivist",
            round=2,
            severity="high",
            score=1.0,
            eta=1.0,
        )

    def __getitem__(self, key):
        return getattr(self, key)

    def get(self, key, default=None):
        return getattr(self, key, default)

    def __contains__(self, key):
        return hasattr(self, key)


def call_eta_int_modulator(func, record):
    """
    Call the real function while adapting only to obvious signature shapes.
    The expected target shape is eta_int_modulator(record), but this keeps the
    falsifier runnable if optional/defaulted parameters exist.
    """
    sig = inspect.signature(func)
    args = []
    kwargs = {}

    for name, param in sig.parameters.items():
        if param.kind in (param.VAR_POSITIONAL, param.VAR_KEYWORD):
            continue

        lname = name.lower()

        if "record" in lname or "finding" in lname or "case" in lname:
            value = record
        elif "history" in lname or "prior" in lname or "previous" in lname:
            value = [record]
        elif "near" in lname and "copy" in lname:
            value = True
        elif "recid" in lname or "repeat" in lname:
            value = True
        elif "compliant" in lname:
            value = True
        elif "eta" in lname or "score" in lname or "base" in lname or "current" in lname:
            value = 1.0
        elif param.default is not inspect._empty:
            continue
        else:
            value = record

        if param.kind == param.KEYWORD_ONLY:
            kwargs[name] = value
        else:
            args.append(value)

    return func(*args, **kwargs)


def main():
    func = target.eta_int_modulator
    record = ProbeRecord()

    # Snapshot mutable state before calling the real implementation.
    # This avoids deriving the assertion from values that an in-place-mutating
    # implementation may have changed during the call.
    before_call_state = copy.deepcopy(record.__dict__)

    result = call_eta_int_modulator(func, record)

    precondition_held = (
        before_call_state["compliant"] is True
        and before_call_state["any_near_copy"] is True
        and (
            before_call_state["recidivist"] is True
            or before_call_state["recidivism"] is True
            or before_call_state["cross_round_recidivist"] is True
        )
    )
    assert precondition_held, "falsifier setup failed to establish the reviewed precondition"

    if result == 1.0:
        print(
            "FALSIFIED: eta_int_modulator returned 1.0 for a compliant "
            "near-copy/recidivist record, bypassing the severe 0.60 penalty tier."
        )
        raise AssertionError(
            "eta_int_modulator bypasses near-copy/recidivism penalty when record.compliant is True"
        )

    # Fixed/absent defect: any non-1.0 modulator means the compliant early return
    # did not bypass the penalty path for this precondition.
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

