#!/usr/bin/env python3
"""
Falsifier for the review finding:

check_sibling_admissibility compares AlternativeRecord.alternative_text after
parse_alternative_block has stripped the contrast statement.  If true, two
alternatives with identical bodies but materially different contrast statements
are rejected as sibling/cross-round near-copies even though their full
submissions are below the near-copy threshold.

Raises AssertionError / prints FALSIFIED iff the real module exhibits the bug.
Exits cleanly otherwise.
"""

from __future__ import annotations

import dataclasses
import inspect
import sys
from typing import Any

import bench.dm._divergence as div  # absolute import of the real target module


FINDING_ID = "finding-contrast-strip-falsifier"
DIMENSION = "mechanism"
THRESHOLD = 0.80

PRIMARY = (
    "Primary proposal uses a centralized scheduler with synchronous quorum "
    "approval and conservative rollback semantics."
)

BODY = (
    "Shared orchard kernel keeps the same candidate mechanism body unchanged "
    "for this admissibility probe."
)

# Long, disjoint token sets make full body+contrast Jaccard far below threshold,
# while stripped body-vs-body Jaccard remains 1.0.
CONTRAST_A_TOKENS = " ".join(f"alphatok{i}" for i in range(140))
CONTRAST_B_TOKENS = " ".join(f"betatok{i}" for i in range(140))

CONTRAST_A = (
    "This alternative differs from primary on mechanism in that "
    + CONTRAST_A_TOKENS
)
CONTRAST_B = (
    "This alternative differs from primary on mechanism in that "
    + CONTRAST_B_TOKENS
)


# Step 1: read the real code via inspect.  This also fails early if the expected
# real path is not present.
try:
    _REAL_CHECK_SOURCE = inspect.getsource(div.check_sibling_admissibility)
except AttributeError:
    print("NOT FALSIFIED: real module has no check_sibling_admissibility")
    sys.exit(0)

try:
    _REAL_PARSE_SOURCE = inspect.getsource(div.parse_alternative_block)
except AttributeError:
    _REAL_PARSE_SOURCE = ""


def _set(obj: Any, name: str, value: Any) -> None:
    try:
        setattr(obj, name, value)
    except Exception:
        object.__setattr__(obj, name, value)


def _make_policy() -> Any:
    """Best-effort construction of the module's real divergence policy/config."""
    candidates = []
    for name, obj in vars(div).items():
        if isinstance(obj, type) and (
            "policy" in name.lower()
            or "config" in name.lower()
            or "directive" in name.lower()
        ):
            candidates.append(obj)

    # Prefer classes that appear to carry the near-copy threshold.
    candidates.sort(
        key=lambda c: (
            not hasattr(c, "__dataclass_fields__"),
            "near_copy" not in str(getattr(c, "__dataclass_fields__", {})).lower(),
        )
    )

    for cls in candidates:
        try:
            policy = cls()
        except Exception:
            if not dataclasses.is_dataclass(cls):
                continue
            kwargs = {}
            ok = True
            for f in dataclasses.fields(cls):
                if f.default is not dataclasses.MISSING:
                    continue
                if f.default_factory is not dataclasses.MISSING:  # type: ignore[attr-defined]
                    continue

                n = f.name.lower()
                if "threshold" in n:
                    kwargs[f.name] = THRESHOLD
                elif "enabled" in n:
                    kwargs[f.name] = True
                elif "min" in n and "contrast" in n:
                    kwargs[f.name] = 1
                elif "dimension" in n:
                    kwargs[f.name] = [DIMENSION]
                else:
                    ok = False
                    break
            if not ok:
                continue
            try:
                policy = cls(**kwargs)
            except Exception:
                continue

        # Force thresholds/minimums to make the precondition explicit.
        for attr in (
            "near_copy_threshold",
            "sibling_near_copy_threshold",
            "sibling_isomorphism_threshold",
            "isomorphism_threshold",
            "recidivism_threshold",
            "cross_round_recidivism_threshold",
        ):
            if hasattr(policy, attr):
                _set(policy, attr, THRESHOLD)

        for attr in ("enabled", "divergence_directive_enabled"):
            if hasattr(policy, attr):
                _set(policy, attr, True)

        for attr in ("min_contrast_chars", "minimum_contrast_chars"):
            if hasattr(policy, attr):
                _set(policy, attr, 1)

        return policy

    return None


POLICY = _make_policy()


def _raw_block(idx: int, contrast: str) -> str:
    return f"""
Alternative {idx}
Dimension: {DIMENSION}
Alternative text:
{BODY}

Contrast statement: {contrast}
""".strip()


def _mapped_value_for_param(
    param_name: str,
    *,
    raw: str | None = None,
    idx: int = 1,
    alternatives: list[Any] | None = None,
    prior: list[Any] | None = None,
) -> tuple[bool, Any]:
    n = param_name.lower()

    if "prior" in n:
        return True, prior if prior is not None else []
    if "alternative" in n and ("records" in n or n.endswith("s") or "list" in n):
        return True, alternatives if alternatives is not None else []
    if n in {"alternatives", "alts", "records"}:
        return True, alternatives if alternatives is not None else []
    if "policy" in n or "config" in n or "directive" in n:
        return True, POLICY
    if "threshold" in n:
        return True, THRESHOLD
    if "primary" in n and "text" in n:
        return True, PRIMARY
    if "finding" in n and "id" in n:
        return True, FINDING_ID
    if "dimension" in n:
        return True, DIMENSION
    if "round" in n:
        return True, 2
    if "index" in n or n == "idx":
        return True, idx
    if raw is not None and (
        "block" in n
        or n in {"text", "raw", "raw_text", "alternative_text"}
        or ("alternative" in n and "text" in n)
    ):
        return True, raw

    return False, None


def _call_with_mapped_kwargs(fn: Any, **context: Any) -> Any:
    sig = inspect.signature(fn)
    kwargs = {}
    for p in sig.parameters.values():
        if p.kind in (p.VAR_POSITIONAL, p.VAR_KEYWORD):
            continue
        if p.kind is p.POSITIONAL_ONLY:
            raise TypeError("positional-only parameter present")

        ok, value = _mapped_value_for_param(p.name, **context)
        if ok:
            kwargs[p.name] = value
        elif p.default is inspect._empty:
            raise TypeError(f"cannot map required parameter {p.name!r}")

    return fn(**kwargs)


def _call_parse(raw: str, idx: int) -> Any | None:
    if not hasattr(div, "parse_alternative_block"):
        return None

    fn = div.parse_alternative_block

    attempts = [
        lambda: _call_with_mapped_kwargs(fn, raw=raw, idx=idx),
        lambda: fn(raw, FINDING_ID, PRIMARY, POLICY),
        lambda: fn(raw, PRIMARY, FINDING_ID, POLICY),
        lambda: fn(raw, FINDING_ID, PRIMARY),
        lambda: fn(raw, PRIMARY),
        lambda: fn(raw),
    ]

    for attempt in attempts:
        try:
            result = attempt()
        except Exception:
            continue

        if isinstance(result, (list, tuple)) and result:
            for item in result:
                if hasattr(item, "alternative_text"):
                    return item
        if hasattr(result, "alternative_text"):
            return result

    return None


def _make_record_direct(contrast: str) -> Any:
    """Fallback construction using the real AlternativeRecord dataclass."""
    cls = getattr(div, "AlternativeRecord", None)
    if cls is None:
        raise RuntimeError("module has neither parseable records nor AlternativeRecord")

    kwargs = {}
    if dataclasses.is_dataclass(cls):
        for f in dataclasses.fields(cls):
            n = f.name.lower()
            if n == "primary_finding_id" or ("finding" in n and "id" in n):
                kwargs[f.name] = FINDING_ID
            elif n == "alternative_text":
                kwargs[f.name] = BODY
            elif n == "dimension":
                kwargs[f.name] = DIMENSION
            elif n == "contrast_statement":
                kwargs[f.name] = contrast
            elif n == "isomorphism_score":
                kwargs[f.name] = 0.0
            elif n == "sibling_max_isomorphism":
                kwargs[f.name] = 0.0
            elif n == "prior_round_isomorphism":
                kwargs[f.name] = 0.0
            elif n == "admissible":
                kwargs[f.name] = True
            elif n == "admissibility_gate_passed":
                kwargs[f.name] = True
            elif n == "rejection_reasons":
                kwargs[f.name] = []
            elif f.default is not dataclasses.MISSING:
                pass
            elif f.default_factory is not dataclasses.MISSING:  # type: ignore[attr-defined]
                pass
            else:
                raise RuntimeError(f"cannot construct AlternativeRecord field {f.name!r}")
        return cls(**kwargs)

    return cls(
        primary_finding_id=FINDING_ID,
        alternative_text=BODY,
        dimension=DIMENSION,
        contrast_statement=contrast,
    )


def _normalise_for_check(record: Any, contrast: str) -> Any:
    """
    Ensure the downstream real check starts from the intended precondition:
    stripped body in alternative_text, contrast stored separately, initially
    admissible.
    """
    _set(record, "primary_finding_id", FINDING_ID)
    _set(record, "alternative_text", BODY)
    _set(record, "dimension", DIMENSION)
    _set(record, "contrast_statement", contrast)

    if hasattr(record, "admissible"):
        _set(record, "admissible", True)
    if hasattr(record, "admissibility_gate_passed"):
        _set(record, "admissibility_gate_passed", True)
    if hasattr(record, "rejection_reasons"):
        reasons = getattr(record, "rejection_reasons")
        if isinstance(reasons, list):
            reasons.clear()
        else:
            _set(record, "rejection_reasons", [])
    if hasattr(record, "sibling_max_isomorphism"):
        _set(record, "sibling_max_isomorphism", 0.0)
    if hasattr(record, "prior_round_isomorphism"):
        _set(record, "prior_round_isomorphism", 0.0)

    return record


def _record(contrast: str, idx: int) -> Any:
    raw = _raw_block(idx, contrast)
    parsed = _call_parse(raw, idx)
    if parsed is not None:
        return _normalise_for_check(parsed, contrast)
    return _normalise_for_check(_make_record_direct(contrast), contrast)


def _score(a: str, b: str) -> float:
    if hasattr(div, "score_isomorphism"):
        return float(div.score_isomorphism(a, b))

    # Conservative fallback if the public scorer was renamed/removed.
    import re

    toks_a = set(re.findall(r"[A-Za-z][A-Za-z0-9_]*", a.lower()))
    toks_b = set(re.findall(r"[A-Za-z][A-Za-z0-9_]*", b.lower()))
    if not toks_a and not toks_b:
        return 1.0
    if not toks_a or not toks_b:
        return 0.0
    return len(toks_a & toks_b) / len(toks_a | toks_b)


def _full_submission(record: Any) -> str:
    if hasattr(div, "_recidivism_text"):
        try:
            return str(div._recidivism_text(record))
        except Exception:
            pass
    return (
        (getattr(record, "alternative_text", "") or "")
        + " "
        + (getattr(record, "contrast_statement", "") or "")
    ).strip()


def _snapshot(record: Any) -> dict[str, Any]:
    return {
        "alternative_text": getattr(record, "alternative_text", None),
        "contrast_statement": getattr(record, "contrast_statement", None),
        "admissible": getattr(record, "admissible", None),
        "admissibility_gate_passed": getattr(record, "admissibility_gate_passed", None),
        "sibling_max_isomorphism": getattr(record, "sibling_max_isomorphism", None),
        "prior_round_isomorphism": getattr(record, "prior_round_isomorphism", None),
        "rejection_reasons": list(getattr(record, "rejection_reasons", []) or []),
    }


def _call_check(alternatives: list[Any], prior: list[Any] | None = None) -> Any:
    fn = div.check_sibling_admissibility

    attempts = [
        lambda: _call_with_mapped_kwargs(fn, alternatives=alternatives, prior=prior),
        lambda: fn(alternatives, POLICY),
        lambda: fn(alternatives, THRESHOLD),
        lambda: fn(alternatives),
    ]

    # Common shape for a cross-round extension.
    if prior is not None:
        attempts.insert(1, lambda: fn(alternatives, prior, POLICY))
        attempts.insert(2, lambda: fn(alternatives, prior, THRESHOLD))

    last_exc = None
    for attempt in attempts:
        try:
            return attempt()
        except TypeError as exc:
            last_exc = exc
            continue

    raise RuntimeError(f"could not call real check_sibling_admissibility: {last_exc}")


def _is_rejected(record: Any) -> bool:
    admissible = getattr(record, "admissible", True)
    gate = getattr(record, "admissibility_gate_passed", True)
    return admissible is False or gate is False


def _has_isomorphism_reason(record: Any, kind: str) -> bool:
    reasons = " ".join(str(r).lower() for r in (getattr(record, "rejection_reasons", []) or []))
    return kind in reasons or "isomorph" in reasons or "near" in reasons or "copy" in reasons


def _sibling_defect_present() -> tuple[bool, str]:
    alt1 = _record(CONTRAST_A, 1)
    alt2 = _record(CONTRAST_B, 2)
    alternatives = [alt1, alt2]

    body_score = _score(alt1.alternative_text, alt2.alternative_text)
    full_score = _score(_full_submission(alt1), _full_submission(alt2))

    if not (body_score >= THRESHOLD and full_score < THRESHOLD):
        return (
            False,
            f"precondition not met for sibling probe: body_score={body_score:.4f}, "
            f"full_score={full_score:.4f}",
        )

    # Required snapshot before the real in-place-mutating call.
    before = [_snapshot(a) for a in alternatives]

    _call_check(alternatives)

    after2 = _snapshot(alt2)
    sib_iso = getattr(alt2, "sibling_max_isomorphism", 0.0) or 0.0

    if (
        _is_rejected(alt2)
        and (sib_iso >= THRESHOLD or _has_isomorphism_reason(alt2, "sibling"))
        and before[1]["alternative_text"] == BODY
        and before[1]["contrast_statement"] == CONTRAST_B
    ):
        return (
            True,
            "sibling admissibility used stripped alternative_text rather than "
            "body+contrast full submission "
            f"(body_score={body_score:.4f}, full_score={full_score:.4f}, "
            f"before={before[1]}, after={after2})",
        )

    return (
        False,
        f"sibling probe not falsified: body_score={body_score:.4f}, "
        f"full_score={full_score:.4f}, before={before[1]}, after={after2}",
    )


def _cross_round_defect_present() -> tuple[bool, str]:
    prior_alt = _record(CONTRAST_A, 1)
    current_alt = _record(CONTRAST_B, 1)

    body_score = _score(prior_alt.alternative_text, current_alt.alternative_text)
    full_score = _score(_full_submission(prior_alt), _full_submission(current_alt))

    if not (body_score >= THRESHOLD and full_score < THRESHOLD):
        return (
            False,
            f"precondition not met for cross-round probe: body_score={body_score:.4f}, "
            f"full_score={full_score:.4f}",
        )

    before = _snapshot(current_alt)

    try:
        _call_check([current_alt], prior=[prior_alt])
    except Exception as exc:
        return False, f"cross-round path not callable through check_sibling_admissibility: {exc}"

    after = _snapshot(current_alt)
    prior_iso = getattr(current_alt, "prior_round_isomorphism", 0.0) or 0.0

    if (
        _is_rejected(current_alt)
        and (prior_iso >= THRESHOLD or _has_isomorphism_reason(current_alt, "prior"))
        and before["alternative_text"] == BODY
        and before["contrast_statement"] == CONTRAST_B
    ):
        return (
            True,
            "cross-round recidivism used stripped alternative_text rather than "
            "body+contrast full submission "
            f"(body_score={body_score:.4f}, full_score={full_score:.4f}, "
            f"before={before}, after={after})",
        )

    return (
        False,
        f"cross-round probe not falsified: body_score={body_score:.4f}, "
        f"full_score={full_score:.4f}, before={before}, after={after}",
    )


def main() -> None:
    sibling_bad, sibling_msg = _sibling_defect_present()
    cross_bad, cross_msg = _cross_round_defect_present()

    failures = []
    if sibling_bad:
        failures.append(sibling_msg)
    if cross_bad:
        failures.append(cross_msg)

    if failures:
        msg = "FALSIFIED: " + " | ".join(failures)
        print(msg)
        raise AssertionError(msg)

    print("NOT FALSIFIED")
    print(sibling_msg)
    print(cross_msg)


if __name__ == "__main__":
    main()
